const CACHE='progress-v2';const SHELL=['./','./index.html','./manifest.json','./icons/icon.svg'];const STATIC_HOSTS=[self.location.hostname];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL.map(p=>new URL(p,self.registration.scope).toString()))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;const url=new URL(req.url);if(url.origin!==self.location.origin)return;
if(req.mode==='navigate'||req.destination==='document'){e.respondWith(fetch(req).then(r=>{const c=r.clone();caches.open(CACHE).then(k=>k.put('./index.html',c));return r}).catch(()=>caches.match('./index.html').then(r=>r||new Response('<h1>Offline</h1>',{status:503,headers:{'Content-Type':'text/html'}}))));return}
e.respondWith(caches.match(req).then(cached=>{const fetched=fetch(req).then(r=>{if(r&&r.status===200&&r.type==='basic'){const c=r.clone();caches.open(CACHE).then(k=>k.put(req,c))}return r}).catch(()=>cached);return cached||fetched}))});
